"""Axis I: psi(V) = S.  psi(V) is generated by omega, the currents and psi(u26), psi(u17) (all in S, Thm i5), so
psi(V) c S.  Conversely we show that the weight-two closure of {A_2, omega, g.psi(u26), g.psi(u17)} under the
products a(1)b is 120-dimensional (rank modulo p, a lower bound over K), hence equals U_2 = S_2, so S c psi(V)."""
import sys, os, json, pickle, time
HERE = os.path.abspath('.'); sys.path.insert(0, HERE); sys.path.insert(0, os.path.abspath('../zhu'))
import zhu_common as Z
from zhu_common import E, V, K, np, P
exec(open(HERE + '/i5_membership.py').read().split('res = {}')[0].split("os.chdir('../generation-forte')")[1].replace('import lattice_voa as V, exact_engine as E, Kfield as K', ''))
S = E.setup(0); T = S['T']
d = pickle.load(open(Z.ZD + '/U2_lowering_basis.pkl', 'rb'))
aff = [b[3] for b, lab in ((b, d['hv'][b[0]][0]) for b in d['basis']) if lab.startswith('A:')]
cur = {n: Z.kv(T[n]) for n in ('f1', 'f2')}
def lowerings(v):
    out = []; vi = v
    while vi:
        vj = vi
        while vj: out.append(vj); vj = Z.prod(cur['f2'], 0, vj)
        vi = Z.prod(cur['f1'], 0, vi)
    return out
gens = aff + [Z.kv(V.OMEGA)] + lowerings(u26) + lowerings(u17)
pos = {k: i for i, k in enumerate(V.basis(2))}
ech = E.Ech(len(pos)); basis = []; words = []; indices = {}
def offer(v, word):
    if v and ech.add(E.modp_vec(v, pos, len(pos))):
        indices[id(v)] = len(basis); basis.append(v); words.append(word)
        return True
    return False
for j, v in enumerate(gens): offer(v, ['seed', j])
print('initial rank', len(basis))
new = list(basis); it = 0
while new and len(basis) < 120:
    it += 1; nxt = []
    for a in new:
        for b in list(basis):
            for w in (Z.prod(a, 1, b),):
                if offer(w, ['mode1', indices[id(a)], indices[id(b)]]): nxt.append(w)
    new = nxt; print('iteration', it, 'rank', len(basis), flush=True)
json.dump({'rank_weight2_closure': len(basis)}, open(HERE + '/i6_generation.json', 'w'))

assert len(basis) == 120

def serialize(v):
    return [[str(k), [str(a) for a in coefficients]] for k, coefficients in v.items()]
json.dump({'prime': P, 'sqrt13': E.F.s13, 'sqrt_minus3': E.F.s3,
           'rank': len(basis), 'words': words, 'seed_vectors': [serialize(v) for v in gens],
           'basis_vectors': [serialize(v) for v in basis]},
          open(HERE + '/i6_rank_certificate.json', 'w'), indent=1)
